/* C API of the Rust port of `vert.c`, generated by rust-anything. */
#ifndef VERT_RS_H
#define VERT_RS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <sys/types.h>

double VertDistance(double xi, double yi, double zi, double xj, double yj, double zj, int which);
double VertResponse(double d0, double d1, double diffusivity, double currTime);
double VertIntegral(double xi, double yi, double zi, double xj, double yj, double bhLength, double bhTopDepth, double bhDiameter, double diffusivity, double currTime);
double VertDoubleIntegral(double xi, double yi, double xj, double yj, int same, double bhLength, double bhTopDepth, double bhDiameter, double diffusivity, double currTime);
int VertNumLntts(double bhLength, double diffusivity, double maxSimYears);
double VertLntts(double bhLength, double diffusivity, double maxSimYears, int k);
double VertGFunction(int nx, int ny, double spacing, double bhLength, double bhTopDepth, double bhDiameter, double diffusivity, double maxSimYears, int k);
double VertFrictionFactor(double reynoldsNum);
double VertPipeConductionResistance(double outDia, double innerDia, double k);
double VertTimeSS(double bhLength, double diffusivity);

/* The same functions under `rust_anything_` names, for shadow runs. */
double rust_anything_VertDistance(double xi, double yi, double zi, double xj, double yj, double zj, int which);
double rust_anything_VertResponse(double d0, double d1, double diffusivity, double currTime);
double rust_anything_VertIntegral(double xi, double yi, double zi, double xj, double yj, double bhLength, double bhTopDepth, double bhDiameter, double diffusivity, double currTime);
double rust_anything_VertDoubleIntegral(double xi, double yi, double xj, double yj, int same, double bhLength, double bhTopDepth, double bhDiameter, double diffusivity, double currTime);
int rust_anything_VertNumLntts(double bhLength, double diffusivity, double maxSimYears);
double rust_anything_VertLntts(double bhLength, double diffusivity, double maxSimYears, int k);
double rust_anything_VertGFunction(int nx, int ny, double spacing, double bhLength, double bhTopDepth, double bhDiameter, double diffusivity, double maxSimYears, int k);
double rust_anything_VertFrictionFactor(double reynoldsNum);
double rust_anything_VertPipeConductionResistance(double outDia, double innerDia, double k);
double rust_anything_VertTimeSS(double bhLength, double diffusivity);

#endif /* VERT_RS_H */
